fun findUser(id: Long): Map<String, Any>? {
    if (id <= 0) return null
    return mapOf("id" to id, "name" to "user-$id")
}

class Stack<T> {
    private val items = mutableListOf<T>()
    fun push(value: T) = items.add(value)
    fun pop(): T? = items.removeLastOrNull()
}

fun <T, K> List<T>.groupByKey(keyFn: (T) -> K): Map<K, List<T>> {
    val grouped = linkedMapOf<K, MutableList<T>>()
    for (item in this) {
        grouped.getOrPut(keyFn(item)) { mutableListOf() }.add(item)
    }
    return grouped
}

